// TestHuntD_HealthCheckWatcherPollByLicense records, for a sequence of license / feature-flag
// states applied at runtime, how many health_check queries one PollAndNotify of the app's
// health-check watcher makes.
func TestHuntD_HealthCheckWatcherPollByLicense(t *testing.T) {
	const name = "TestHuntD_HealthCheckWatcherPollByLicense"

	th := SetupConfig(t, func(cfg *model.Config) {
		cfg.FeatureFlags.HealthDashboard = true
	})
	th.App.Srv().SetLicense(nil)
	t.Cleanup(func() { th.App.Srv().SetLicense(nil) })

	// Keep the background watcher loop from polling during the recording.
	oldInterval := jobs.DefaultWatcherPollingInterval
	jobs.DefaultWatcherPollingInterval = 1 << 30
	t.Cleanup(func() { jobs.DefaultWatcherPollingInterval = oldInterval })

	jobServer := th.Server.Jobs
	counting := &huntDPollStore{Store: jobServer.Store}
	jobServer.Store = counting
	t.Cleanup(func() { jobServer.Store = counting.Store })

	ch := th.Server.Channels()
	ch.startHealthCheckWorkersWithRun(func(request.CTX) error { return nil })
	t.Cleanup(ch.stopHealthCheckWorkers)
	if ch.healthCheckWorkers == nil || ch.healthCheckWorkers.Watcher == nil {
		t.Fatal("health-check workers not started")
	}

	type step struct {
		License string `json:"license"`
		Flag    bool   `json:"flag"`
	}

	// Hand-picked sequence: unlicensed, below Professional, license added at runtime, removed
	// again, flag off with a license, cloud variants.
	steps := []step{
		{"nil", true},
		{"nil", true},
		{"e10", true},
		{"e20", true},
		{"professional", true},
		{"nil", true},
		{"enterprise", true},
		{"enterprise", false},
		{"nil", false},
		{"professional_cloud", true},
		{"e20_cloud", true},
		{"enterprise_cloud", true},
		{"test_default", true},
		{"nil", true},
	}

	unlicensedKinds := []string{"nil", "e10", "e20", "e20_cloud"}
	allKinds := []string{"nil", "e10", "e20", "e20_cloud", "professional", "professional_cloud", "enterprise", "enterprise_cloud", "test_default"}
	r := rand.New(rand.NewSource(40364))
	for i := 0; i < 200; i++ {
		if i%2 == 0 {
			// Changed branch: flag on, no Professional license.
			steps = append(steps, step{unlicensedKinds[r.Intn(len(unlicensedKinds))], true})
		} else {
			// Untouched paths: licensed, or flag off.
			steps = append(steps, step{allKinds[r.Intn(len(allKinds))], r.Intn(4) != 0})
		}
	}

	currentFlag := true
	for i, s := range steps {
		s := s
		if s.Flag != currentFlag {
			flag := s.Flag
			th.App.UpdateConfig(func(cfg *model.Config) { cfg.FeatureFlags.HealthDashboard = flag })
